17	export const _e = new THREE.Euler(), _q = new THREE.Quaternion();
18	const _o = new THREE.Vector3(), _s = new THREE.Vector3(), _m = new THREE.Matrix4();
19	export function placePart(mesh: THREE.InstancedMesh, i: number, base: THREE.Vector3, q: THREE.Quaternion, ox: number, oy: number, sx: number, sy: number, sz: number) {
20	  _o.set(ox, oy, 0).applyQuaternion(q).add(base);
21	  mesh.setMatrixAt(i, _m.compose(_o, q, _s.set(sx, sy, sz)));
22	}
