59	/* Không cấp phát mỗi khung (D-018). Đèn pha/hậu chỉ hiện khi đêm > 0,3 (applyNight đặt visible trước hàm này): khi ẩn không ghi ma trận đèn;
60	   vị trí xe (v.s) vẫn cộng dồn như cũ nên khung đèn hiện lại thì ma trận được ghi đúng chỗ ngay trong khung đó */
61	export function updateTraffic(dt: number) {
62	  const lamps = vHead.visible;
63	  for (let i = 0; i < vehicles.length; i++) {
64	    const v = vehicles[i], P = v.path, range = P.max - P.min, T = TYPES[v.type];
65	    if (P.hidden) { hideAt(i, lamps); continue; } // làn tắt bằng nút bật/tắt
66	    v.s += v.dir * v.speed * dt;
