68	    if ((P === PATHS.axis || P === PATHS.ttl) && vanished(i, weatherFx.clear)) { hideAt(i, lamps); continue; }   // đóng cầu (bão): dọn dần xe trên Cầu Rồng, Trần Thị Lý
69	    let yaw: number, pitch = 0;
